using Abastalia.CashRegister.Contracts;
using Abastalia.Fiscal.Contracts;
using Abastalia.Inventory.Contracts;
using Abastalia.SharedKernel;

namespace Abastalia.Sales.Domain;

public enum SalePriceLevel { Retail, Wholesale }

internal enum SaleStatus { Completed, Voided }

internal sealed class Sale
{
    /// <summary>Receipt number shown to people (local, increasing). The fiscal number is <see cref="ENcf"/>.</summary>
    public long Number { get; set; }
    /// <summary>Generated by the register: retrying the same sale returns the same result (idempotency key).</summary>
    public Guid Id { get; set; }
    public Guid ShiftId { get; set; }
    public Guid RegisterId { get; set; }
    public string Register { get; set; } = "";
    public Guid CashierId { get; set; }
    public string Cashier { get; set; } = "";
    public Guid? CustomerId { get; set; }
    public string? CustomerName { get; set; }
    public string? CustomerRnc { get; set; }
    public EcfType DocumentType { get; set; }
    public string ENcf { get; set; } = "";
    public string SecurityCode { get; set; } = "";
    public string QrUrl { get; set; } = "";
    /// <summary>When the e-CF was signed (printed under the QR); null on sales recorded before TK-148.</summary>
    public DateTime? SignedUtc { get; set; }
    /// <summary>e-NCF range expiry, printed on the 31.</summary>
    public DateOnly? SequenceExpiresOn { get; set; }
    /// <summary>Issued while the DGII could not be reached: the receipt carries the contingency legend.</summary>
    public bool Contingency { get; set; }
    public SalePriceLevel PriceLevel { get; set; }
    public decimal Gross { get; set; }
    public decimal Discount { get; set; }
    public decimal Subtotal { get; set; }
    public decimal Itbis { get; set; }
    public decimal Total { get; set; }
    public decimal Change { get; set; }
    /// <summary>Cash centavos kept because change is given in whole pesos.</summary>
    public decimal Rounding { get; set; }
    public SaleStatus Status { get; set; }
    /// <summary>Bumped by an atomic update before a void or return reads the sale: it locks the row, so they run one at a time.</summary>
    public int Version { get; set; }
    public DateTime DateUtc { get; set; }
    public DateTime? VoidedUtc { get; set; }
    public string? VoidReason { get; set; }
    public Guid? VoidedById { get; set; }
    public string? VoidENcf { get; set; }
    public Guid? SupervisorId { get; set; }
    public List<SaleLine> Lines { get; set; } = [];
    public List<SalePayment> Payments { get; set; } = [];
}

internal sealed class SaleLine
{
    public Guid Id { get; set; }
    public Guid SaleId { get; set; }
    public int Position { get; set; }
    public Guid ProductId { get; set; }
    public Guid? PresentationId { get; set; }
    public Guid CategoryId { get; set; }
    public string Description { get; set; } = "";
    public UnitOfMeasure Unit { get; set; }
    public decimal Quantity { get; set; }
    /// <summary>Base units per sold unit; inventory moves Quantity × Factor.</summary>
    public decimal Factor { get; set; }
    public decimal ListPrice { get; set; }
    public decimal UnitPrice { get; set; }
    public decimal Gross { get; set; }
    public decimal Discount { get; set; }
    public ItbisRate ItbisRate { get; set; }
    public decimal Itbis { get; set; }
    public decimal Total { get; set; }
    /// <summary>Cost per sold unit at the moment of the sale (historical cost for profit reports).</summary>
    public decimal UnitCost { get; set; }
    public string? Note { get; set; }
    public string? ScaleLabel { get; set; }
    public decimal ReturnedQuantity { get; set; }
}

internal sealed class SalePayment
{
    public Guid Id { get; set; }
    public Guid SaleId { get; set; }
    public PaymentMethod Method { get; set; }
    public decimal Amount { get; set; }
    public decimal? Received { get; set; }
    public string? Reference { get; set; }
}

internal sealed class SaleReturn
{
    public Guid Id { get; set; }
    public Guid SaleId { get; set; }
    public Guid ShiftId { get; set; }
    public PaymentMethod Method { get; set; }
    public decimal Total { get; set; }
    public decimal Itbis { get; set; }
    public string ENcf { get; set; } = "";
    public string Reason { get; set; } = "";
    public DateTime DateUtc { get; set; }
    public Guid UserId { get; set; }
    public Guid? SupervisorId { get; set; }
    public List<ReturnLine> Lines { get; set; } = [];
}

internal sealed class ReturnLine
{
    public Guid ReturnId { get; set; }
    public Guid SaleLineId { get; set; }
    public decimal Quantity { get; set; }
    public decimal Total { get; set; }
    public decimal Itbis { get; set; }
    public bool Restocked { get; set; }
}

/// <summary>A cart parked at a register to serve the next customer; the register stores the draft as JSON.</summary>
internal sealed class HeldSale
{
    public Guid Id { get; set; }
    public Guid ShiftId { get; set; }
    public Guid UserId { get; set; }
    public string Label { get; set; } = "";
    public string Content { get; set; } = "";
    public decimal Total { get; set; }
    public DateTime CreatedUtc { get; set; }
}

internal static class SalesErrors
{
    public static readonly Error SaleNotFound = Error.NotFound("Sales.SaleNotFound", "La venta no existe.");
    public static readonly Error ProductUnavailable = Error.Conflict("Sales.ProductUnavailable", "Un producto de la venta no existe o está desactivado.");
    public static readonly Error AlreadyVoided = Error.Conflict("Sales.AlreadyVoided", "La venta ya está anulada.");
    public static readonly Error OutsideShift = Error.Conflict("Sales.OutsideShift", "El turno de esa venta ya cerró. Haga una devolución (nota de crédito).");
    public static readonly Error HasReturns = Error.Conflict("Sales.HasReturns", "La venta tiene devoluciones; no se puede anular.");
    public static readonly Error ReturnQuantityExceeded = Error.Validation("Sales.ReturnQuantityExceeded", "No se puede devolver más de lo que se vendió.");
    public static readonly Error DuplicateScaleLabel = Error.Conflict("Sales.DuplicateScaleLabel", "Esa etiqueta de balanza ya está en la venta.");
    public static readonly Error MethodUnavailable = Error.Validation("Sales.MethodUnavailable", "Ese medio de pago necesita un cliente con cuenta.");
    public static readonly Error DuplicateId = Error.Conflict("Sales.DuplicateId", "Ese número de venta ya se usó para otra venta. Vuelva a cobrar.");
    public static readonly Error ScaleLabelMismatch = Error.Conflict("Sales.ScaleLabelMismatch", "La etiqueta de balanza es de otro producto.");
    public static readonly Error RncRequired = Error.Validation("Sales.RncRequired", "Este comprobante necesita el RNC o la cédula del cliente.");
    /// <summary>R11 A16: a card or transfer payment carries its authorization or transfer number (the store can turn it off).</summary>
    public static readonly Error ReferenceRequired = Error.Validation("Sales.ReferenceRequired",
        "Escriba el número de autorización de la tarjeta o el de la transferencia.");

    public static Error MethodExceeded(PaymentMethod method, decimal maximum) =>
        Error.Validation("Sales.MethodExceeded", $"Por {PaymentMethodNames.Display(method)} se pueden devolver como máximo RD$ {maximum:N2} (lo que se cobró así).");

    public static Error TotalChanged(decimal total) =>
        Error.Conflict("Sales.TotalChanged", $"El total cambió a RD$ {total:N2}. Revise la venta antes de cobrar.") with
        {
            Details = new Dictionary<string, string[]> { ["total"] = [total.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture)] },
        };
}
